<script setup lang="ts">
import {Head,Link,router,useForm} from '@inertiajs/vue3';
import {reactive,ref} from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import Pagination from '../../components/Pagination.vue';
import type {PageRows} from '../../types/salesOrder';
import type {OpsProgram,OpsParticipant} from '../../types/operations';
type Answer={id:number;peserta_id:number;nama:string;instansi:string;times?:string;tgl_isi:string};
type Detail={id:number;id_survey_jawaban:number;pertanyaan_teks:string;nilai:number|null;jawaban:string|null;nama:string};
const props=defineProps<{program:OpsProgram;rows:PageRows<OpsParticipant>;filters:Record<string,string>;blockers:string[];warnings:string[];canManage:boolean;survey:{enabled:boolean;status:string;url:string|null;answers:Answer[];details:Detail[];total:number;recap:{pertanyaan:string;rata:number|null;nilai:Record<string,number>;pilihan:Record<string,number>|null;jawaban:Detail[]}[]}}>();
const tab=props.filters.tab || 'peserta';
const f=reactive({q:'',tab,...props.filters});
const closing=ref(false), editing=ref<OpsParticipant|null>(null), mode=ref('nama'), viewed=ref<number|null>(null);
const closeForm=useForm({});
const form=useForm({nama_sertifikat:'',sumber_konfirmasi:'',status_kirim:'belum',tgl_kirim:'',kirim_via:'',draft_kirim_date:'',lsp:'',skema:'',metode:'',hasil:'belum',no_sertifikat_bnsp:'',berlaku_sampai:'',tgl_terima_bnsp:'',tgl_kirim_bnsp:'',id_card:'belum',bukti:null as File|null});
function edit(x:OpsParticipant,action:string){editing.value=x;mode.value=action;form.clearErrors();form.defaults({nama_sertifikat:x.nama_sertifikat || x.nama,sumber_konfirmasi:'',status_kirim:x.status_kirim || 'belum',tgl_kirim:x.tgl_kirim || '',kirim_via:x.kirim_via || '',draft_kirim_date:x.draft_kirim_date || '',lsp:x.sertifikat_lsp || x.lsp || '',skema:x.skema || '',metode:x.metode || '',hasil:x.hasil || 'belum',no_sertifikat_bnsp:x.no_sertifikat_bnsp || '',berlaku_sampai:x.sertifikat_berlaku || x.tgl_habis_sertifikat || '',tgl_terima_bnsp:x.tgl_terima_bnsp || '',tgl_kirim_bnsp:x.tgl_kirim_bnsp || '',id_card:x.id_card || 'belum',bukti:null});form.reset();}
function save(){if(editing.value)form.post(`/manage-peserta/peserta/${editing.value.id}/${mode.value}`,{forceFormData:true,onSuccess:()=>editing.value=null});}
</script>
<template><Head :title="program.nomor"/><AppLayout title="Manage Peserta"><div class="page-head"><h1>{{program.nomor}}</h1><Link href="/manage-peserta">Semua Program</Link></div><section class="panel"><h2>{{program.judul}}</h2><p>{{program.jenis.toUpperCase()}} · {{program.company}} · {{program.tgl_mulai}} s.d. {{program.tgl_selesai}} · {{program.lokasi}}</p><p>Trainer: {{program.trainer}} · Target {{program.target_peserta}} peserta.</p><p v-if="program.closed_date" class="notice">Closed {{program.closed_date}}. Administrasi sertifikat/BNSP tetap tersedia.</p><template v-else><p v-for="b in blockers" :key="b">{{b}}</p><button v-if="canManage" type="button" @click="closing=true">Close Program</button></template></section><nav class="tabs" aria-label="Data program"><Link v-for="t in ['peserta','sertifikat','survey']" :key="t" :href="`/manage-peserta/${program.id}?tab=${t}`" :aria-current="tab===t?'page':undefined">{{t==='peserta'?'Daftar Peserta':t==='sertifikat'?'Sertifikat':'Survey'}}</Link></nav>
<template v-if="tab!=='survey'"><form class="filters" @submit.prevent="router.get(`/manage-peserta/${program.id}`,f)"><label>Cari peserta<input v-model="f.q" type="search" maxlength="100"/></label><button>Terapkan</button><a :href="`/manage-peserta/${program.id}/excel`">Export Excel</a><a v-if="tab==='sertifikat' && rows.total" :href="`/manage-peserta/${program.id}/pdf/draft`">Draft semua peserta</a></form><p v-if="tab==='sertifikat'" class="notice">Penerbitan sertifikat resmi menunggu format, penandatangan, dan aturan BA. Draft tanpa nomor untuk konfirmasi nama.</p><div class="table-wrap"><table><thead><tr><th>Peserta</th><th>Instansi / kontak</th><th>{{tab==='peserta'?'Quotation':'Sertifikat'}}</th><th>Aksi</th></tr></thead><tbody><tr v-for="x in rows.data" :key="x.id"><td>{{x.nama}}<small v-if="tab==='sertifikat'">Nama sertifikat: {{x.nama_sertifikat || x.nama}}<br>{{x.nama_konfirmasi_date?'Nama dikonfirmasi '+x.nama_konfirmasi_date:x.draft_kirim_date?'Draft dikirim '+x.draft_kirim_date:'Belum dicek'}}</small></td><td>{{x.instansi}}<small>{{x.no_wa}} · {{x.email}}</small></td><td v-if="tab==='peserta'">{{x.nomor_quotation}}</td><td v-else>{{x.no_sertifikat || 'Belum terbit'}}<small>{{x.status_kirim || 'belum'}}</small><template v-if="x.tipe!=='Pelatihan'"><small>BNSP: {{x.hasil || 'belum'}} · {{x.no_sertifikat_bnsp}}<br>LSP {{x.sertifikat_lsp}} · {{x.skema}} · {{x.metode}}<br>Diterima {{x.tgl_terima_bnsp || '—'}} · Dikirim {{x.tgl_kirim_bnsp || '—'}}<br>ID card {{x.id_card || 'belum'}} · Berlaku {{x.sertifikat_berlaku || '—'}}</small><a v-if="x.has_bnsp_file" :href="`/documents/bnsp/${x.sertifikat_id}`">Unduh BNSP</a></template></td><td><details><summary>Aksi {{x.nama}}</summary><div class="stack" v-if="tab==='peserta'"><a :href="`/manage-peserta/${program.id}/pdf/name-table?peserta=${x.id}`">Cetak Name Table peserta ini</a><a :href="`/manage-peserta/${program.id}/pdf/name-table`">Cetak Name Table semua peserta</a><a :href="`/manage-peserta/${program.id}/pdf/hadir`">Cetak Daftar Hadir semua peserta</a></div><div v-else class="stack"><a :href="`/manage-peserta/${program.id}/pdf/draft?peserta=${x.id}`">Draft sertifikat</a><button v-if="canManage" type="button" @click="edit(x,'draft-kirim')">Catat draft dikirim</button><button v-if="canManage" type="button" @click="edit(x,'nama')">Konfirmasi nama</button><button v-if="canManage && x.tipe!=='Pelatihan'" type="button" @click="edit(x,'bnsp')">Pengiriman &amp; Sertifikasi BNSP</button><button v-if="canManage && x.no_sertifikat" type="button" @click="edit(x,'pengiriman')">Pengiriman Sertifikat</button><button disabled title="Menunggu pengesahan BA">Buat Sertifikat resmi</button></div></details></td></tr><tr v-if="!rows.data.length"><td colspan="4" class="empty">Belum ada peserta Deal sesuai filter.</td></tr></tbody></table></div><Pagination :page="rows" label="Halaman peserta"/></template>
<section v-else class="panel stack"><h2>Survey peserta</h2><p v-if="!survey.enabled" class="notice">Survei publik belum diaktifkan. Pertanyaan dan aturan final menunggu BA; contoh hanya untuk pengujian.</p><p>Status {{survey.status}} · {{survey.answers.length}} dari {{survey.total}} peserta sudah mengisi.</p><a v-if="survey.url" :href="survey.url">{{survey.url}}</a><div v-if="canManage && !program.closed_date"><button :disabled="!survey.enabled" @click="router.post(`/manage-peserta/${program.id}/survey/buka`)">Buka survey</button><button :disabled="survey.status!=='buka'" @click="router.post(`/manage-peserta/${program.id}/survey/tutup`)">Tutup survey</button></div><a :href="`/manage-peserta/${program.id}/survey/excel`">Export Excel jawaban</a><div class="table-wrap"><table><thead><tr><th>Peserta</th><th>Status</th><th>Jawaban</th></tr></thead><tbody><tr v-for="x in rows.data" :key="x.id"><td>{{x.nama}} · {{x.instansi}}</td><td>{{survey.answers.find(a=>a.peserta_id===x.id)?.tgl_isi || 'Belum mengisi'}}</td><td><button v-if="survey.answers.some(a=>a.peserta_id===x.id)" @click="viewed=survey.answers.find(a=>a.peserta_id===x.id)?.id || null">Lihat jawaban</button></td></tr></tbody></table></div><Pagination :page="rows" label="Halaman peserta Survey"/><h2>Rekap jawaban</h2><section v-for="s in survey.recap" :key="s.pertanyaan"><h3>{{s.pertanyaan}}</h3><p v-if="s.rata!==null">Rata-rata {{s.rata.toFixed(1)}} · Jumlah per nilai: {{s.nilai}}</p><p v-if="s.pilihan">Jumlah per pilihan: {{s.pilihan}}</p><p v-for="d in s.jawaban" :key="d.id">{{d.nama}}: {{d.jawaban}}</p></section></section>
<ConfirmDialog v-if="closing" title="Close Program" confirm-label="Close Program" :busy="closeForm.processing" @cancel="closing=false" @confirm="closeForm.post(`/manage-peserta/${program.id}/close`,{onSuccess:()=>closing=false})"><p>Program tidak dapat dibuka kembali. Quotation, invoice, serta pengajuan biaya baru akan dikunci.</p><p v-for="w in warnings" :key="w">{{w}}</p><p v-for="b in blockers" :key="b" class="error">{{b}}</p><p v-for="e in closeForm.errors" :key="e" class="error" role="alert">{{e}}</p></ConfirmDialog>
<ConfirmDialog v-if="editing" :title="mode==='nama'?'Konfirmasi nama':mode==='draft-kirim'?'Catat draft dikirim':mode==='pengiriman'?'Pengiriman Sertifikat':'Pengiriman & Sertifikasi BNSP'" :busy="form.processing" @cancel="editing=null" @confirm="save"><p>{{editing.nama}}</p><template v-if="mode==='nama'"><label>Nama di sertifikat<input v-model="form.nama_sertifikat" maxlength="150" required/></label><label>Sumber konfirmasi (mis. WA 12-11)<input v-model="form.sumber_konfirmasi" maxlength="150"/></label></template><label v-else-if="mode==='draft-kirim'">Tanggal draft dikirim<input v-model="form.draft_kirim_date" type="date" required/></label><div v-else-if="mode==='pengiriman'" class="form-grid"><label>Status kirim<select v-model="form.status_kirim"><option value="belum">Belum dikirim</option><option value="soft">Dikirim softcopy</option><option value="hard">Dikirim hardcopy</option></select></label><label>Tanggal kirim<input v-model="form.tgl_kirim" type="date"/></label><label>Dikirim lewat<input v-model="form.kirim_via" maxlength="100"/></label></div><div v-else class="form-grid"><label>LSP<input v-model="form.lsp" maxlength="100"/></label><label>Skema<input v-model="form.skema" maxlength="150"/></label><label>Metode<select v-model="form.metode"><option value="">Belum diisi</option><option value="ukom">Uji Kompetensi</option><option value="porto">Portofolio</option></select></label><label>Hasil<select v-model="form.hasil"><option value="belum">Belum diuji</option><option value="kompeten">Kompeten</option><option value="belum_kompeten">Belum Kompeten</option></select></label><label>No. Sertifikat BNSP<input v-model="form.no_sertifikat_bnsp" maxlength="60"/></label><label>Berlaku sampai<input v-model="form.berlaku_sampai" type="date"/></label><label>Diterima dari LSP<input v-model="form.tgl_terima_bnsp" type="date"/></label><label>Dikirim ke peserta<input v-model="form.tgl_kirim_bnsp" type="date"/></label><label>ID Card<select v-model="form.id_card"><option value="belum">Belum</option><option value="sudah">Sudah</option></select></label><label>File BNSP PDF/JPG/PNG, maks. 5 MB<input type="file" accept=".pdf,.jpg,.jpeg,.png" @change="form.bukti=($event.target as HTMLInputElement).files?.[0] || null"/></label></div><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p></ConfirmDialog>
<ConfirmDialog v-if="viewed" title="Jawaban Survey" confirm-label="Tutup" @cancel="viewed=null" @confirm="viewed=null"><p v-for="d in survey.details.filter(x=>x.id_survey_jawaban===viewed)" :key="d.id"><strong>{{d.pertanyaan_teks}}</strong><br>{{d.nilai ?? d.jawaban}}</p></ConfirmDialog>
</AppLayout></template>
